package com.example.campsitelottery

import androidx.compose.ui.test.assertIsNotEnabled
import androidx.compose.ui.test.assertTextEquals
import androidx.compose.ui.test.junit4.createComposeRule
import androidx.compose.ui.test.onNodeWithTag
import androidx.compose.ui.test.onNodeWithText
import androidx.compose.ui.test.performClick
import androidx.navigation.compose.rememberNavController
import androidx.test.ext.junit.runners.AndroidJUnit4
import org.junit.Assert.assertEquals
import org.junit.Rule
import org.junit.Test
import org.junit.runner.RunWith

/**
 * Documentation generated by Claude
 * UI tests for [AdminCampsiteRatingsScreen], using an in-memory repository.
 */
@RunWith(AndroidJUnit4::class)
class AdminCampsiteRatingsScreenTest {

    @get:Rule
    val composeRule = createComposeRule()

    private val site = Campsite(campsiteId = "site1", ownerId = "owner", name = "Lakeside Pines")

    private fun repoWith(vararg ratings: Pair<String, Int>) =
        InMemoryRatingRepository(listOf(site), raterNames = mapOf("spammer" to "Spam Bot", "fan" to "Sam")).apply {
            ratings.forEach { (user, stars) -> submitRating("site1", user, stars, {}, { throw it }) }
        }

    private fun showScreen(repo: InMemoryRatingRepository) {
        val shown = site.copy(
            ratingSum = repo.totalsFor("site1")!!.sum,
            ratingCount = repo.totalsFor("site1")!!.count,
        )
        composeRule.setContent {
            AdminCampsiteRatingsScreen(
                rememberNavController(),
                campsiteId = "site1",
                ratingRepository = repo,
                loadCampsite = { _, onResult -> onResult(shown) },
            )
        }
    }

    @Test
    fun listsEveryRatingWithRaterNames() {
        showScreen(repoWith("spammer" to 1, "fan" to 5))
        composeRule.onNodeWithText("Spam Bot").assertExists()
        composeRule.onNodeWithText("Sam").assertExists()
        composeRule.onNodeWithTag("adminRatingsSummary").assertTextEquals("3.0 ★ (2 ratings)")
    }

    @Test
    fun removingAfterConfirmUpdatesListAndAverage() {
        val repo = repoWith("spammer" to 1, "fan" to 5)
        showScreen(repo)
        composeRule.onNodeWithTag("removeRating_spammer").performClick()
        composeRule.onNodeWithTag("confirmRemoveRatingButton").performClick()

        composeRule.onNodeWithTag("adminRating_spammer").assertDoesNotExist()
        composeRule.onNodeWithTag("adminRating_fan").assertExists()
        composeRule.onNodeWithTag("adminRatingsSummary").assertTextEquals("5.0 ★ (1 rating)")
        composeRule.onNodeWithTag("adminRatingsMessage").assertTextEquals("Removed Spam Bot's rating (★☆☆☆☆).")
        assertEquals(RatingPolicy.Totals(sum = 5, count = 1), repo.totalsFor("site1"))
    }

    @Test
    fun cancellingKeepsTheRating() {
        val repo = repoWith("spammer" to 1)
        showScreen(repo)
        composeRule.onNodeWithTag("removeRating_spammer").performClick()
        composeRule.onNodeWithText("Cancel").performClick()

        composeRule.onNodeWithTag("adminRating_spammer").assertExists()
        assertEquals(RatingPolicy.Totals(sum = 1, count = 1), repo.totalsFor("site1"))
    }

    @Test
    fun removingTheLastRatingShowsEmptyState() {
        showScreen(repoWith("spammer" to 1))
        composeRule.onNodeWithTag("removeRating_spammer").performClick()
        composeRule.onNodeWithTag("confirmRemoveRatingButton").performClick()

        composeRule.onNodeWithTag("noRatingsText").assertExists()
        composeRule.onNodeWithTag("adminRatingsSummary").assertTextEquals("No ratings yet")
    }

    @Test
    fun failedRemovalShowsError() {
        val repo = repoWith("spammer" to 1)
        showScreen(repo)
        repo.failWith = IllegalStateException("offline")
        composeRule.onNodeWithTag("removeRating_spammer").performClick()
        composeRule.onNodeWithTag("confirmRemoveRatingButton").performClick()

        composeRule.onNodeWithTag("adminRatingsError").assertTextEquals("offline")
    }

    @Test
    fun loadFailureOffersRetry() {
        val repo = repoWith("fan" to 4).apply { failWith = IllegalStateException("offline") }
        showScreen(repo)
        composeRule.onNodeWithTag("retryRatingsButton").assertExists()
        repo.failWith = null
        composeRule.onNodeWithTag("retryRatingsButton").performClick()
        composeRule.onNodeWithTag("adminRating_fan").assertExists()
    }

    @Test
    fun removeIsDisabledUntilTheCampsiteLoads() {
        val repo = repoWith("spammer" to 1)
        composeRule.setContent {
            AdminCampsiteRatingsScreen(
                rememberNavController(),
                campsiteId = "site1",
                ratingRepository = repo,
                loadCampsite = { _, _ -> }, // never finishes
            )
        }
        composeRule.onNodeWithTag("removeRating_spammer").assertIsNotEnabled()
    }

    @Test
    fun changedRatingIsNotRemoved() {
        val repo = repoWith("spammer" to 1)
        showScreen(repo)
        repo.submitRating("site1", "spammer", 5, {}, { throw it }) // changed after the list loaded
        composeRule.onNodeWithTag("removeRating_spammer").performClick()
        composeRule.onNodeWithTag("confirmRemoveRatingButton").performClick()

        composeRule.onNodeWithTag("adminRatingsError").assertTextEquals(RatingPolicy.CHANGED_MESSAGE)
        assertEquals(RatingPolicy.Totals(sum = 5, count = 1), repo.totalsFor("site1"))
    }

    @Test
    fun campsiteLoadFailureOffersRetry() {
        val repo = repoWith("spammer" to 1)
        composeRule.setContent {
            AdminCampsiteRatingsScreen(
                rememberNavController(),
                campsiteId = "site1",
                ratingRepository = repo,
                loadCampsite = { _, onResult -> onResult(null) },
            )
        }
        composeRule.onNodeWithTag("adminRatingsCampsiteError").assertExists()
        composeRule.onNodeWithTag("retryCampsiteButton").assertExists()
        composeRule.onNodeWithTag("removeRating_spammer").assertDoesNotExist()
    }
}
